package com.joysistvi.CyberAccess.controller;
import com.joysistvi.CyberAccess.model.Conversation; import com.joysistvi.CyberAccess.service.ConversationServiceImpl; import java.sql.SQLException; import java.util.List;
public class ConversationController {private final ConversationServiceImpl service;public ConversationController(){this(new ConversationServiceImpl());}public ConversationController(ConversationServiceImpl s){service=s;}public List<Conversation> getAll()throws SQLException{return service.getAll();}public List<Conversation> getByUser(int id)throws SQLException{return service.getByUser(id);}public boolean send(Conversation x)throws SQLException{return service.send(x);}public boolean setStatus(int id,String status)throws SQLException{return service.setStatus(id,status);}public boolean delete(int id)throws SQLException{return service.delete(id);}}
